package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Rejects a create-owner request once the maximum number of owners
 * ({@link DailyOwnerLimitException#LIMIT}) have already been created on the same business day,
 * counted by {@link Owner#getRegistrationDate()}. The day counted is this request's <em>adjusted</em>
 * business day: the effective registration date — supplied in the request or defaulted to the server
 * date — rolled forward off a weekend or public holiday to the next non-holiday business day,
 * matching what {@link BuildOwner} will store.
 * Runs before {@link SaveOwner}, so the new owner is not yet counted; a business day already holding
 * 100 owners causes the 101st request to fail with 429.
 */
public class EnsureDailyOwnerLimit {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        LocalDate effective = request.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        LocalDate businessDay = BusinessDays.rollForward(effective);
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (businessDay.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        if (count >= DailyOwnerLimitException.LIMIT) {
            throw new DailyOwnerLimitException(businessDay, count);
        }
    }
}

===== BuildOwner.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
            throws FutureRegistrationDateException {
        Owner owner = ownerMapper.toOwner(request);
        // A newly created owner is not deleted.
        owner.setDeleted(false);
        LocalDate effective = owner.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        // A supplied registration date cannot be in the future; reject a date later than the
        // server's current date with a 400 before it is rolled onto a business day.
        else if (effective.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(effective);
        }
        // The effective registration date must fall on a business day, whether supplied in the
        // request or defaulted to the server date; a weekend or public holiday rolls forward to the
        // next non-holiday business day.
        owner.setRegistrationDate(BusinessDays.rollForward(effective));
        built.set(owner);
    }
}

===== AssignMemberId.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} — the
 * region code derived from the postcode (NSW/VIC/QLD, else {@code UNKNOWN}), the two-digit fiscal year
 * the registrationDate falls in, the first 8 upper-case hex characters of SHA-256 over
 * {@code normalizedTelephone + lastName}, and a single Luhn check digit over the digits of
 * {@code <REGION><FY><HASH8>} (see {@link MemberId}, e.g. {@code NSW271A2B3C4D5}). The base id is fully
 * determined by the owner's region, fiscal year and hashed identity.
 *
 * <p>When that base id collides with an existing owner's {@code memberId}, it is de-duplicated by
 * appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique (e.g.
 * {@code NSW271A2B3C4D5-2}). Runs before {@link SaveOwner}, so {@link OwnerRepository#findAll()}
 * returns only the owners that predate this create.
 */
public class AssignMemberId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setMemberId(uniqueId(baseId(owner), assignedIds(ownerRepository)));
    }

    /**
     * The owner's base memberId before any collision suffix, formatted {@code <REGION><FY><HASH8><CHK>}.
     * Fully determined by the owner, so equal owners produce the same base.
     */
    private static String baseId(Owner owner) {
        String regionCode = OwnerRegion.identifierRegionCode(owner.getPostcode());
        String fiscalYearCode = OwnerMembership.fiscalYearCode(owner.getRegistrationDate());
        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
        return MemberId.of(regionCode, fiscalYearCode, hash8);
    }

    /**
     * {@code base} de-duplicated against {@code existing} by appending {@code -<n>} with the smallest
     * {@code n} of 2 or more that makes it unique (e.g. {@code NSW271A2B3C4D5-2}); {@code base} itself
     * when already free.
     */
    private static String uniqueId(String base, Set<String> existing) {
        String id = base;
        for (int n = 2; existing.contains(id); n++) {
            id = base + "-" + n;
        }
        return id;
    }

    /** The ids already assigned to existing owners — the set a new memberId must avoid colliding with. */
    private static Set<String> assignedIds(OwnerRepository ownerRepository) {
        Set<String> existing = new HashSet<>();
        for (Owner other : ownerRepository.findAll()) {
            if (other.getMemberId() != null) {
                existing.add(other.getMemberId());
            }
        }
        return existing;
    }
}

===== AssignHouseholdId.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's deterministic {@code householdId} — the first 12 hex characters of SHA-256 over
 * the normalized lastName and postcode (see {@link OwnerIdentity#deriveHouseholdId}). Because the id
 * is a pure function of (lastName, postcode), every owner that shares a lastName and postcode resolves
 * to the same value automatically, with no back-filling and regardless of creation order. It also
 * records {@code householdSize} — the number of owners that share this household after the create
 * (the existing members with the same computed householdId, plus this new owner). Runs before
 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
 * create.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = OwnerIdentity.householdIdOf(owner.getLastName(), owner.getPostcode());
        owner.setHouseholdId(householdId);

        // Count the existing members of this household (same computed householdId) plus this owner.
        int size = 1;
        for (Owner existing : ownerRepository.findAll()) {
            String existingHousehold = OwnerIdentity.householdIdOf(
                    existing.getLastName(), existing.getPostcode());
            if (householdId.equals(existingHousehold)) {
                size++;
            }
        }
        owner.setHouseholdSize(size);
    }
}

===== CapMembershipLevel.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records the new owner's {@code membershipLevelCap}: the ceiling its membership level may reach,
 * being one above the current maximum {@link OwnerMembership#level(Owner) membershipLevel} among the
 * existing members of its household (those sharing the owner's computed {@code householdId}). With no
 * existing household member the cap is left unset (null), so no cap applies.
 *
 * <p>Runs after {@link AssignHouseholdId} (so the owner's {@code householdId} is set) and before
 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
 * create. {@link OwnerMembership#level(Owner)} applies the recorded cap.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return;
        }
        Integer maxLevel = null;
        for (Owner existing : ownerRepository.findAll()) {
            String existingHousehold = OwnerIdentity.householdIdOf(
                    existing.getLastName(), existing.getPostcode());
            if (householdId.equals(existingHousehold)) {
                int level = OwnerMembership.level(existing);
                if (maxLevel == null || level > maxLevel) {
                    maxLevel = level;
                }
            }
        }
        if (maxLevel != null) {
            owner.setMembershipLevelCap(maxLevel + 1);
        }
    }
}

