    private static String groupInThrees(String digits) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < digits.length(); i++) {
            if (i > 0 && i % 3 == 0) {
                builder.append(' ');
            }
            builder.append(digits.charAt(i));
        }
        return builder.toString();
    }
}

